<template>
  <section class="teams-page">
    <header class="page-heading"><div><p class="eyebrow">Owner workspace</p><h1>Assistant teams</h1><p>Manage separate accounts for ITSCO, Next Level Up and Inner Strength. Duties become available only after their verification passes.</p></div><button type="button" @click="load" :disabled="busy">Refresh</button></header>
    <p v-if="error" role="alert" class="notice notice--error">{{ error }}</p><p v-if="message" role="status" class="notice">{{ message }}</p>
    <AssistantBillingRules />
    <section class="panel"><h2>Prepare the accounts</h2><p>Preview the eligible accounts before creating them. Agencies without active schools receive no School Support account.</p><div class="agency-choices"><label v-for="agency in agencies" :key="agency.id"><input type="checkbox" :value="Number(agency.id)" v-model="selectedAgencies" @change="preview=null" />{{ agency.name }}</label></div><div class="actions"><button type="button" @click="provision(true)" :disabled="busy || !selectedAgencies.length">Preview accounts</button><button type="button" class="secondary" @click="provision(false)" :disabled="busy || !preview">Create previewed accounts</button></div><div v-if="preview" class="preview"><h3>Provisioning preview</h3><AssistantPacket :value="preview" /></div></section>
    <section class="panel"><div class="section-heading"><h2>Accounts</h2><label class="filter-label">Agency<select v-model="agencyFilter"><option value="">All three agencies</option><option v-for="agency in agencies" :key="agency.id" :value="String(agency.id)">{{ agency.name }}</option></select></label></div><p v-if="loading" role="status">Loading assistant accounts…</p><p v-else-if="!filteredAccounts.length" class="muted">No assistant accounts match this agency.</p><div class="account-grid"><article v-for="account in filteredAccounts" :key="account.id" class="account-card"><div class="card-heading"><h3>{{ account.displayName }}</h3><span class="badge">{{ account.status }}</span></div><p class="account-email">{{ account.email }}</p><p>{{ account.agencyName }} · {{ roleLabel(account.subrole) }}</p><dl><dt>Enabled duties</dt><dd>{{ account.capabilities?.length || 0 }}</dd><dt>Group email</dt><dd>{{ account.groupStatus || 'not provisioned' }}</dd><dt>Policy</dt><dd>{{ account.policyRevision || 'pending' }}</dd><dt>BAA</dt><dd>{{ account.baaStatus || 'pending' }}</dd></dl><div class="actions"><button type="button" @click="edit(account)">Manage</button><button type="button" class="secondary" @click="accountAction(account,'provision-group')" :disabled="busy">Provision group</button><button type="button" class="secondary" @click="accountAction(account,'prepare')" :disabled="busy">Prepare test</button></div></article></div></section>
    <section v-if="selected" class="panel editor"><div class="section-heading"><div><p class="eyebrow">{{ selected.agencyName }}</p><h2>Manage {{ selected.displayName }}</h2></div><button type="button" class="secondary" @click="selected=null">Close</button></div><form @submit.prevent="save"><div class="form-grid"><label>Status<select v-model="form.status"><option>pending</option><option>active</option><option>paused</option><option>disabled</option></select></label><label>External processor BAA<select v-model="form.baaStatus"><option value="pending">Pending verification</option><option value="verified">Verified</option></select></label></div><fieldset><legend>Verified duties</legend><p class="muted">The server checks the current capability test receipts before accepting a grant.</p><label v-for="capability in selectedCatalog?.capabilities || []" :key="capability.key" class="check"><input type="checkbox" :value="capability.key" v-model="form.capabilities" />{{ capability.label || capability.key }}</label><p v-if="!selectedCatalog?.capabilities?.length" class="muted">This role has no operational duties.</p></fieldset><fieldset><legend>Schedule</legend><label class="check"><input type="checkbox" v-model="form.schedule.enabled" />Enable the configured schedule after verification</label><div class="form-grid"><label>Morning start (America/Denver)<input type="time" v-model="form.schedule.localTime" /></label><label>Additional run times (optional)<input v-model="additionalTimes" placeholder="11:00, 14:00" /></label></div><label v-if="selected.subrole==='team_lead'">Afternoon review (America/Denver)<input type="time" v-model="afternoonTime" /></label><div class="weekday-choices"><label v-for="(day,index) in ['Sun','Mon','Tue','Wed','Thu','Fri','Sat']" :key="day" class="check"><input type="checkbox" :value="index" v-model="form.schedule.weekdays" />{{ day }}</label></div><p class="muted">The browser runner must be configured separately to wake each account. This schedule defines when work is due.</p></fieldset><fieldset><legend>Screened narrative policy</legend><p class="muted">Clinical and compliance work requires approved screening and a passed sample review. Removing obvious names alone does not establish HIPAA de-identification.</p><label>External service covered by this policy<input v-model="form.privacyPolicy.externalService" maxlength="160" placeholder="Named browser agent / processor service" /></label><label>BAA coverage reference<input v-model="form.privacyPolicy.baaReference" maxlength="500" placeholder="Reviewed agreement reference; no credentials or private links" /></label><label>Screening sample-review reference<input v-model="form.privacyPolicy.sampleReviewReference" maxlength="500" placeholder="Saved sample-review evidence reference" /></label><label class="check"><input type="checkbox" v-model="form.privacyPolicy.enabled" />Enable the narrative screening policy</label><label class="check"><input type="checkbox" v-model="form.privacyPolicy.approved" />Owner reviewed and approved this policy</label><label class="check"><input type="checkbox" v-model="form.privacyPolicy.sampleReviewPassed" />The sample screening review passed</label><label>Policy revision<input v-model="form.privacyPolicy.revision" required maxlength="80" /></label><template v-if="selected.subrole==='compliance'"><label class="check"><input type="checkbox" v-model="form.privacyPolicy.compliancePolicy.approved" />Approve the compliance checklist</label><label>Checklist version<input v-model="form.privacyPolicy.compliancePolicy.version" maxlength="80" /></label><label>Approved policy source reference<input v-model="form.privacyPolicy.compliancePolicy.reference" maxlength="500" placeholder="Reviewed policy/manual reference; no credentials or private links" /></label><label>Approved dated rules (JSON array)<textarea v-model="complianceRules" rows="4" placeholder="Each rule needs text, applicabilityVerified, effectiveFrom and effectiveThrough." /></label></template></fieldset><fieldset v-if="selected.subrole==='marketing'"><legend>Approved website copy</legend><p class="muted">List only this agency's approved pages and exact owner-approved hero heading/subtitle variants. Publishing cannot change URLs, provider content, prices, scripts or clinical claims. A saved variant still needs the separate verified publication duty.</p><label>Approved pages and text variants<textarea v-model="marketingPolicyText" rows="12" spellcheck="false" aria-describedby="marketing-policy-help" /></label><p id="marketing-policy-help" class="muted">Use the page reference from this agency's website settings. Supported text fields: heroTitle and heroSubtitle. Keep approvedContentReviewed false until every supplied variant has been reviewed.</p></fieldset><label>New app password (optional)<input v-model="form.newPassword" type="password" autocomplete="new-password" minlength="16" placeholder="Leave blank to retain the current password" /></label><label>Reason for this change<textarea v-model="form.reason" rows="3" required maxlength="2000" /></label><p class="muted">Account changes are recorded and alert Michael. Password values are never included in the alert.</p><button type="submit" :disabled="busy">Save account changes</button></form><form @submit.prevent="verify" class="verification"><h3>Record a verification receipt</h3><p>Record evidence from an actual external browser test before enabling a duty.</p><div class="form-grid"><label>Observed outcome<select v-model="receipt.outcome"><option>PASS</option><option>FAIL</option><option>BLOCKED</option><option>NOT_RUN</option></select></label><label>Tested duty<select v-model="receipt.capability" required><option disabled value="">Choose duty</option><option v-for="capability in selectedCatalog?.capabilities || []" :key="capability.key" :value="capability.key">{{ capability.label || capability.key }}</option></select></label><label>Release build<input v-model="receipt.buildId" required maxlength="100" /></label></div><label>Evidence reference<input v-model="receipt.evidenceRef" required maxlength="500" placeholder="Reference to the saved test receipt" /></label><label>Verification notes<textarea v-model="receipt.reason" required rows="3" /></label><button type="submit" :disabled="busy">Record test result</button></form></section>
    <section class="panel"><h2>Proposals awaiting review</h2><p><router-link to="/assistant-reviews">Open the human review queue</router-link></p><p v-if="!proposals.length" class="muted">No proposals are waiting.</p><article v-for="proposal in proposals" :key="proposal.ref" class="proposal"><h3>{{ proposal.title || proposal.category || 'Assistant proposal' }}</h3><p>{{ proposal.agencyName || agencies.find(a=>Number(a.id)===Number(proposal.agencyId))?.name }} · {{ proposal.status || proposal.decision }}</p><button type="button" class="secondary" @click="openProposal(proposal.ref)">Review evidence</button></article><div v-if="proposalDetail" class="preview"><AssistantPacket :value="proposalDetail" /><form @submit.prevent="reviewProposal" class="review-form"><label>Decision<select v-model="proposalReview.decision"><option value="accepted">Accept recommendation</option><option value="dismissed">Dismiss</option><option value="more_information">Request more information</option></select></label><label>Reason<textarea v-model="proposalReview.reason" required rows="3" /></label><button type="submit" :disabled="busy">Save review</button></form></div></section>
    <section class="panel"><h2>Restore a website revision</h2><p>Restore the saved previous copy for an approved marketing publication. Review the revision and agency before restoring.</p><form class="review-form" @submit.prevent="rollbackMarketing"><label>Published revision reference<input v-model="rollback.revisionRef" required maxlength="100" /></label><label>Reason<textarea v-model="rollback.reason" required rows="2" maxlength="2000" /></label><button type="submit" :disabled="busy">Restore previous copy</button></form></section><section class="panel"><h2>Account change history</h2><p v-if="!changes.length" class="muted">No changes are recorded yet.</p><div v-for="change in changes" :key="change.id || change.ref" class="change"><strong>{{ change.displayName || change.accountName || accounts.find(a=>a.id===change.accountId)?.displayName || change.eventType || 'Account updated' }}</strong><p>{{ change.reason || change.summary }} <span v-if="change.createdAt">· {{ date(change.createdAt) }}</span></p></div></section>
  </section>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue';
import api from '../../services/api';
import AssistantBillingRules from '../../components/assistants/AssistantBillingRules.vue';
import AssistantPacket from '../../components/assistants/AssistantPacket.vue';
const loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),accounts=ref([]),agencies=ref([]),catalog=ref([]),proposals=ref([]),changes=ref([]),selectedAgencies=ref([2,6,377]),preview=ref(null),agencyFilter=ref(''),selected=ref(null),form=ref({}),afternoonTime=ref('16:00'),additionalTimes=ref(''),complianceRules=ref(''),proposalDetail=ref(null),marketingPolicyText=ref(''),rollback=ref({revisionRef:'',reason:''});
const receipt=ref({capability:'',buildId:'',evidenceRef:'',reason:'',outcome:'NOT_RUN'});const proposalReview=ref({decision:'dismissed',reason:''});
const filteredAccounts=computed(()=>accounts.value.filter(a=>!agencyFilter.value||String(a.agencyId)===agencyFilter.value));
const selectedCatalog=computed(()=>catalog.value.find(c=>c.key===selected.value?.subrole));
const roleLabel=value=>value?String(value).replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()):'Base assistant';
const date=value=>new Date(value).toLocaleString(undefined,{timeZone:'America/Denver'});
const errorText=e=>e?.response?.data?.error?.message||e?.response?.data?.message||'The request could not be completed.';
async function load(){loading.value=true;error.value='';try{const{data}=await api.get('/assistant-accounts');accounts.value=data.accounts||[];agencies.value=data.agencies||[];catalog.value=data.catalog||[];proposals.value=data.proposals||[];changes.value=data.changes||[];}catch(e){error.value=errorText(e);}finally{loading.value=false;}}
async function act(callback,success){busy.value=true;error.value='';message.value='';try{const data=await callback();if(success)message.value=success;return data;}catch(e){error.value=errorText(e);return null;}finally{busy.value=false;}}
async function provision(dryRun){const data=await act(async()=>{const{data}=await api.post('/assistant-accounts/provision',{agencyIds:[...selectedAgencies.value],dryRun});return data;},dryRun?'Preview ready.':'Assistant accounts prepared.');if(data&&dryRun)preview.value=data;if(data&&!dryRun){preview.value=null;await load();}}
function edit(account){selected.value=account;const privacy=account.privacyPolicy||{};form.value={status:account.status,capabilities:[...(account.capabilities||[])],baaStatus:account.baaStatus||'pending',schedule:{enabled:false,timezone:'America/Denver',localTime:account.subrole==='team_lead'?'07:00':'07:10',weekdays:[1,2,3,4,5],...(account.schedule||{})},privacyPolicy:{enabled:false,approved:false,sampleReviewPassed:false,revision:'v1',externalService:'',baaReference:'',sampleReviewReference:'',...privacy,compliancePolicy:{approved:false,version:'',reference:'',rules:[],...(privacy.compliancePolicy||{})}},newPassword:'',reason:''};afternoonTime.value=form.value.schedule.localTimes?.[1]||'16:00';additionalTimes.value=(form.value.schedule.localTimes||[]).slice(selected.value.subrole==='team_lead'?2:1).join(', ');complianceRules.value=JSON.stringify(form.value.privacyPolicy.compliancePolicy.rules,null,2);marketingPolicyText.value=JSON.stringify(privacy.marketing||{approvedContentReviewed:false,sites:[]},null,2);receipt.value={capability:'',buildId:'',evidenceRef:'',reason:'',outcome:'NOT_RUN'};}
async function save(){const body=JSON.parse(JSON.stringify(form.value));body.schedule.timezone='America/Denver';body.schedule.localTimes=[...new Set([body.schedule.localTime,...(selected.value.subrole==='team_lead'?[afternoonTime.value]:[]),...additionalTimes.value.split(',').map(s=>s.trim())].filter(Boolean))];try{const rules=JSON.parse(complianceRules.value||'[]');if(!Array.isArray(rules)||rules.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error();body.privacyPolicy.compliancePolicy.rules=rules;}catch{error.value='Enter a JSON array of reviewed, dated rule objects.';return;}if(!body.newPassword)delete body.newPassword;if(selected.value.subrole==='marketing'){try{body.privacyPolicy.marketing=JSON.parse(marketingPolicyText.value);if(!body.privacyPolicy.marketing||typeof body.privacyPolicy.marketing!=='object'||Array.isArray(body.privacyPolicy.marketing))throw Error();}catch{error.value='Enter a valid approved website-copy policy before saving.';return;}}const id=selected.value.id;const data=await act(async()=>{const{data}=await api.patch(`/assistant-accounts/${id}`,body);return data;},'Account changes saved.');if(data){form.value.newPassword='';await load();const updated=accounts.value.find(a=>a.id===id);if(updated)edit(updated);}}
async function accountAction(account,action){const data=await act(async()=>{const{data}=await api.post(`/assistant-accounts/${account.id}/${action}`);return data;},action==='prepare'?'Preparation requested. Refresh the assistant workspace after the worker finishes.':'Group provisioning checked.');if(data)await load();}
async function verify(){const data=await act(async()=>{const{data}=await api.post(`/assistant-accounts/${selected.value.id}/verify`,receipt.value);return data;},'Verification receipt saved.');if(data)await load();}
async function openProposal(ref){const data=await act(async()=>{const{data}=await api.get(`/assistant-accounts/proposals/${encodeURIComponent(ref)}`);return data;});if(data){proposalDetail.value={...data,ref:data.ref||ref};proposalReview.value={decision:'dismissed',reason:''};}}
async function reviewProposal(){const data=await act(async()=>{const{data}=await api.post(`/assistant-accounts/proposals/${encodeURIComponent(proposalDetail.value.ref)}/review`,proposalReview.value);return data;},'Proposal review saved.');if(data){proposalDetail.value=null;await load();}}
async function rollbackMarketing(){const data=await act(async()=>{const{data}=await api.post('/assistant-accounts/marketing/rollback',rollback.value);return data;},'The previous website copy was restored.');if(data){rollback.value={revisionRef:'',reason:''};await load();}}
onMounted(load);
</script>
<style scoped>
.teams-page{max-width:1180px;margin:auto;padding:32px 24px;color:#1e333d}.page-heading,.section-heading,.card-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.page-heading{margin-bottom:26px}.eyebrow{font-size:12px;letter-spacing:.12em;color:#3c6d62;text-transform:uppercase;font-weight:700}h1{font-size:32px;margin:7px 0 12px}h2{font-size:21px;margin:0 0 14px}h3{font-size:16px;margin:0 0 10px}p{font-size:14px;line-height:1.6;margin:0 0 12px}.muted{color:#627781}.panel{background:var(--card-bg,#fff);padding:24px;border:1px solid #d8e3e8;border-radius:12px;margin-bottom:22px}.account-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:18px}.account-card{padding:20px;border:1px solid #dce5e9;border-radius:9px}.account-email{overflow-wrap:anywhere;color:#486773}.badge{font-size:12px;padding:4px 8px;border-radius:14px;background:#eaf1ed;color:#345f50}.account-card dl{display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:13px;margin:16px 0}.account-card dt{color:#5b727c}.account-card dd{margin:0;text-align:right}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}button{background:#245f56;border:0;border-radius:6px;color:white;padding:10px 13px;cursor:pointer;font-weight:600}button:disabled{opacity:.45;cursor:not-allowed}.secondary{background:#eaf0f3;color:#244c57}.notice{padding:14px;border:1px solid #bdd5cb;border-radius:7px;background:#eff7f2}.notice--error{border-color:#e6b9b9;background:#fff1f1;color:#8b2929}.preview{background:#f4f8fa;padding:20px;margin-top:20px;border-radius:8px}.agency-choices,.weekday-choices{display:flex;flex-wrap:wrap;gap:16px;margin:16px 0}.agency-choices label,.check{display:flex;align-items:center;gap:8px;font-size:13px}.agency-choices input,.check input{width:auto}.editor form,.review-form{display:grid;gap:18px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}label{display:grid;gap:7px;font-size:13px;font-weight:600}input,select,textarea{font:inherit;padding:10px;border:1px solid #bdced6;border-radius:6px;box-sizing:border-box;width:100%;min-width:0}textarea{resize:vertical;line-height:1.6}fieldset{display:grid;gap:14px;border:1px solid #d7e3e8;border-radius:8px;padding:20px}legend{font-weight:700}.verification{margin-top:28px;padding-top:24px;border-top:1px solid #dbe5ea}.proposal,.change{border-top:1px solid #e0e8ec;padding:16px 0}.review-form{margin-top:20px}.filter-label{min-width:180px}@media(max-width:640px){.teams-page{padding:24px 15px}.panel{padding:18px}.page-heading,.section-heading{flex-direction:column}.form-grid{grid-template-columns:1fr}.account-grid{grid-template-columns:1fr}h1{font-size:27px}}
</style>
